<script data-cfasync="false" type="text/javascript">
$(function(){
    window.getSwNews=function(){
        prepareLeft(380);
        $.ajax({url:'addons/Room_wall/system/sw_news.php',type:'POST',dataType:'json',data:{token:utk},success:function(r){
            if(r && r.code==1){window.rwUserId=r.rwUserId||0;window.rwMaxVideoSeconds=r.max_video_seconds||60;window.rwMaxAudioSeconds=r.max_audio_seconds||30;window.rwMaxImageMB=r.max_image_mb||1;window.rwMaxVideoMB=r.max_video_mb||1;window.rwMaxAudioMB=r.max_audio_mb||10;window.rwMaxPostChars=r.max_post_chars||100;window.rwMaxStoryChars=r.max_story_chars||100;window.rwTextStorySeconds=r.story_text_seconds||10;window.rwImageStorySeconds=r.story_image_seconds||5;showLeftPanel(r.content,380,<?php echo json_encode($rwMenuTitle, JSON_UNESCAPED_UNICODE); ?>);$('#rw_news_notify').hide();}
            else callError(system.error);
        },error:function(){callError(system.error);}});
    };
    $('<div id="rw_news_menu" title="<?php echo htmlspecialchars($rwMenuTitle, ENT_QUOTES, 'UTF-8'); ?>" class="head_option" onclick="getSwNews();"><i class="fa fa-book-open i_btm"></i><div id="rw_news_notify" class="head_notify bnotify" style="display:none">!</div></div>').insertAfter('#empty_top_mob');
    <?php if((int)$addons['custom6']===1){ ?>
    if(!$('#chat_left_menu #rw_news_side_menu').length){
        var $rwNewsMenuItem = $('<div id="rw_news_side_menu" class="fmenu_item bhover lmenu_item" onclick="getSwNews();"><div class="fmenu_icon"><i class="fa fa-book-open menui"></i></div><div class="fmenu_text"></div><div class="fmenu_notify"><span class="fnotify bnotify" id="rw_side_notify"></span></div></div>');
        $rwNewsMenuItem.find('.fmenu_text').text(<?php echo json_encode($rwMenuTitle, JSON_UNESCAPED_UNICODE); ?>);
        var $rwMobileNews = $('#chat_left_menu #left_main_content #news_menu').first();
        if($rwMobileNews.length){ $rwMobileNews.after($rwNewsMenuItem); }
    }
    var $rwDesktopMenu = $('#left_menu #left_menu_content');
    if($rwDesktopMenu.length && !$rwDesktopMenu.children('#rw_news_desktop_menu').length){
        var $rwDesktopItem = $('<div id="rw_news_desktop_menu" class="bhover left_menu_item" onclick="getSwNews();"><div class="left_menu_icon"><i class="fa fa-book-open leftmenui"></i><span id="rw_desktop_notify" class="head_notify side_notify bnotify"></span></div></div>');
        $rwDesktopItem.attr('title', <?php echo json_encode($rwMenuTitle, JSON_UNESCAPED_UNICODE); ?>);
        var $rwDesktopNews = $rwDesktopMenu.children('.left_menu_item').filter(function(){ return (($(this).attr('onclick') || '').indexOf('getNews') !== -1); }).first();
        if($rwDesktopNews.length){ $rwDesktopNews.after($rwDesktopItem); } else { $rwDesktopMenu.append($rwDesktopItem); }
    }
    <?php } ?>
    window.rwCheckNotify=function(){
      $.post('addons/Room_wall/system/sw_notify.php',{token:utk},function(r){if(r&&Number(r.notify)>0){$('#rw_news_notify,#rw_side_notify,#rw_desktop_notify').show();}else{$('#rw_news_notify,#rw_side_notify,#rw_desktop_notify').hide();}},'json');
    };
    rwCheckNotify();window.setInterval(rwCheckNotify,15000);
});
</script>
